function getAidocTranslation(key, lang) {
    return (aidocTranslations[lang] && aidocTranslations[lang][key]) ||
           (aidocTranslations.en && aidocTranslations.en[key]) || null;
}

function applyAidocTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.aidoc.") || key.startsWith("review.common."))) {
            const translation = getAidocTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    console.log(`Applied ${count} aidoc translations`);
}

window.addEventListener("languageChanged", e => setTimeout(() => applyAidocTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyAidocTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyAidocTranslations(window.i18n?.getCurrentLanguage() || "en");
}
